SELECT SUBSTR(D.YYYYMMDD,1,6) YM, COUNT(*) KEYS, SUM(CASE WHEN P.K IS NULL THEN 1 ELSE 0 END) NO_PRICE_KEYS, SUM(CASE WHEN P.K IS NULL THEN D.QTY ELSE 0 END) NO_PRICE_QTY, SUM(D.QTY) TOT_QTY
FROM (SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, FCST_TYPE, DOM_EXP, INCOTERMS, YYYYMMDD, SUM(QTY) QTY FROM DM_PLN_CFM_MKT_DEMAND_PLAN
      WHERE DIVISION_ID='40' AND MEASURE='MKT_FCST' AND YYYYMMDD BETWEEN '20261101' AND '20271231' AND QTY<>0
      GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, FCST_TYPE, DOM_EXP, INCOTERMS, YYYYMMDD) D
LEFT JOIN (SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, FCST_TYPE, DOM_EXP, INCOTERMS, YYYYMMDD, 1 K FROM DM_PLN_CFM_SELLING_PRICE
      WHERE DIVISION_ID='40' AND MEASURE='LOC' AND YYYYMMDD BETWEEN '20261101' AND '20271231' AND PRICE<>0) P
 ON P.DIVISION_ID=D.DIVISION_ID AND P.PROJECT_CODE=D.PROJECT_CODE AND P.SCM_SITE_ID=D.SCM_SITE_ID AND P.ITEM_ID=D.ITEM_ID AND P.FCST_TYPE=D.FCST_TYPE AND P.DOM_EXP=D.DOM_EXP AND P.INCOTERMS=D.INCOTERMS AND P.YYYYMMDD=D.YYYYMMDD
GROUP BY SUBSTR(D.YYYYMMDD,1,6) ORDER BY 1
